import{Q as o,J as i}from"./index-BG2hnLSX.js";import{c4 as h}from"./index-DmLsfO5N.js";const l={"3:190":{key:"3:190",sura:3,aya:190,suraName:{ar:"آل عمران",en:"Āl ʿImrān"},page:75,hafs:"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ",uthmani:"إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ",imlaei:"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ",en:{saheeh:{text:"Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding -",src:"saheehQuranEnc"},pickthall:{text:"Lo! In the creation of the heavens and the earth and (in) the difference of night and day are tokens (of His Sovereignty) for men of understanding,",src:"pickthallQuranCom"}}},"36:39":{key:"36:39",sura:36,aya:39,suraName:{ar:"يس",en:"Yā-Sīn"},page:442,hafs:"وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ",uthmani:"وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ",imlaei:"وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ الْقَدِيمِ",en:{saheeh:{text:"And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.",src:"saheehQuranEnc"},pickthall:{text:"And for the moon We have appointed mansions till she return like an old shrivelled palm-leaf.",src:"pickthallQuranCom"}}},"53:49":{key:"53:49",sura:53,aya:49,suraName:{ar:"النجم",en:"al-Najm"},page:528,hafs:"وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ",uthmani:"وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ",imlaei:"وَأَنَّهُ هُوَ رَبُّ الشِّعْرَىٰ",en:{saheeh:{text:"And that it is He who is the Lord of Sirius[1572]",footnote:"[1572] A star worshipped by some of the pagan Arabs.",src:"saheehQuranEnc"},pickthall:{text:"And that He it is Who is the Lord of Sirius;",src:"pickthallQuranCom"}}},"81:15":{key:"81:15",sura:81,aya:15,suraName:{ar:"التكوير",en:"al-Takwīr"},page:586,hafs:"فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ",uthmani:"فَلَآ أُقْسِمُ بِٱلْخُنَّسِ",imlaei:"فَلَا أُقْسِمُ بِالْخُنَّسِ",en:{saheeh:{text:"So I swear by the retreating stars -",src:"saheehQuranEnc"},pickthall:{text:"Oh, but I call to witness the planets,",src:"pickthallQuranCom"}}},"81:16":{key:"81:16",sura:81,aya:16,suraName:{ar:"التكوير",en:"al-Takwīr"},page:586,hafs:"ٱلۡجَوَارِ ٱلۡكُنَّسِ",uthmani:"ٱلْجَوَارِ ٱلْكُنَّسِ",imlaei:"الْجَوَارِ الْكُنَّسِ",en:{saheeh:{text:"Those that run [their courses] and disappear [i.e., set]",src:"saheehQuranEnc"},pickthall:{text:"The stars which rise and set,",src:"pickthallQuranCom"}}},"6:97":{key:"6:97",sura:6,aya:97,suraName:{ar:"الأنعام",en:"al-Anʿām"},page:140,hafs:"وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ",uthmani:"وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ",imlaei:"وَهُوَ الَّذِي جَعَلَ لَكُمُ النُّجُومَ لِتَهْتَدُوا بِهَا فِي ظُلُمَاتِ الْبَرِّ وَالْبَحْرِ ۗ قَدْ فَصَّلْنَا الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ",en:{saheeh:{text:"And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.",src:"saheehQuranEnc"},pickthall:{text:"And He it is Who hath set for you the stars that ye may guide your course by them amid the darkness of the land and the sea. We have detailed Our revelations for a people who have knowledge.",src:"pickthallQuranCom"}}},"2:189":{key:"2:189",sura:2,aya:189,suraName:{ar:"البقرة",en:"al-Baqara"},page:29,hafs:"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ",uthmani:"۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ",imlaei:"يَسْأَلُونَكَ عَنِ الْأَهِلَّةِ ۖ قُلْ هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ ۗ وَلَيْسَ الْبِرُّ بِأَن تَأْتُوا الْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ الْبِرَّ مَنِ اتَّقَىٰ ۗ وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا ۚ وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ",en:{saheeh:{text:'They ask you, [O Muḥammad], about the crescent moons. Say, "They are measurements of time for the people and for ḥajj [pilgrimage]." And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allāh. And enter houses from their doors. And fear Allāh that you may succeed.',src:"saheehQuranEnc"},pickthall:{text:"They ask thee, (O Muhammad), of new moons, say: They are fixed seasons for mankind and for the pilgrimage. It is not righteousness that ye go to houses by the backs thereof (as do the idolaters at certain seasons), but the righteous man is he who wardeth off (evil). So go to houses by the gates thereof, and observe your duty to Allah, that ye may be successful.",src:"pickthallQuranCom"}}},"10:5":{key:"10:5",sura:10,aya:5,suraName:{ar:"يونس",en:"Yūnus"},page:208,hafs:"هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ",uthmani:"هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ",imlaei:"هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالْقَمَرَ نُورًا وَقَدَّرَهُ مَنَازِلَ لِتَعْلَمُوا عَدَدَ السِّنِينَ وَالْحِسَابَ ۚ مَا خَلَقَ اللَّهُ ذَٰلِكَ إِلَّا بِالْحَقِّ ۚ يُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ",en:{saheeh:{text:"It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allāh has not created this except in truth. He details the signs for a people who know.",src:"saheehQuranEnc"},pickthall:{text:"He it is Who appointed the sun a splendour and the moon a light, and measured for her stages, that ye might know the number of the years, and the reckoning. Allah created not (all) that save in truth. He detaileth the revelations for people who have knowledge.",src:"pickthallQuranCom"}}},"36:38":{key:"36:38",sura:36,aya:38,suraName:{ar:"يس",en:"Yā-Sīn"},page:442,hafs:"وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ",uthmani:"وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ",imlaei:"وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ",en:{saheeh:{text:"And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.",src:"saheehQuranEnc"},pickthall:{text:"And the sun runneth on unto a resting-place for him. That is the measuring of the Mighty, the Wise.",src:"pickthallQuranCom"}}},"67:5":{key:"67:5",sura:67,aya:5,suraName:{ar:"الملك",en:"al-Mulk"},page:562,hafs:"وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ",uthmani:"وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ",imlaei:"وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِّلشَّيَاطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ",en:{saheeh:{text:"And We have certainly beautified the nearest heaven with lamps [i.e., stars] and have made [from] them what is thrown at the devils[1714] and have prepared for them the punishment of the Blaze.",footnote:"[1714] Thereby driving them from the heavens and preventing them from eavesdropping. See 72:8-9.",src:"saheehQuranEnc"},pickthall:{text:"And verily We have beautified the world's heaven with lamps, and We have made them missiles for the devils, and for them We have prepared the doom of flame.",src:"pickthallQuranCom"}}},"56:75":{key:"56:75",sura:56,aya:75,suraName:{ar:"الواقعة",en:"al-Wāqiʿa"},page:536,hafs:"۞ فَلَآ أُقۡسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ",uthmani:"۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ",imlaei:"فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ",en:{saheeh:{text:"Then I swear by the setting of the stars,[1618]",footnote:"[1618] Allāh (subḥānahu wa taʿālā) confirms absolutely by oath.",src:"saheehQuranEnc"},pickthall:{text:"Nay, I swear by the places of the stars -",src:"pickthallQuranCom"}}},"56:76":{key:"56:76",sura:56,aya:76,suraName:{ar:"الواقعة",en:"al-Wāqiʿa"},page:536,hafs:"وَإِنَّهُۥ لَقَسَمٞ لَّوۡ تَعۡلَمُونَ عَظِيمٌ",uthmani:"وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ",imlaei:"وَإِنَّهُ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ",en:{saheeh:{text:"And indeed, it is an oath - if you could know - [most] great.",src:"saheehQuranEnc"},pickthall:{text:"And lo! that verily is a tremendous oath, if ye but knew -",src:"pickthallQuranCom"}}}},e=(t,n,s)=>s?{src:t,at:n,quote:s}:{src:t,at:n},r=[{id:"night-day",order:1,narration:"quran-night-day",title:{ar:"تعاقب الليل والنهار",en:"Night after day"},recite:["3:190"],meaning:[{ar:"قال ابن كثير: في خلق السماوات «في ارتفاعها واتساعها» وما فيها من «كواكب سيارات، وثوابت» آياتٌ مشاهدة، واختلافُ الليل والنهار «تعاقبهما وتقارضهما الطول والقصر». وبمثل ذلك فسّره «التفسير الميسر» و«المختصر في التفسير»: تعاقبهما وتفاوتهما طولاً وقِصَراً.",en:"Ibn Kathīr explains that the heavens, 'in their height and breadth', hold signs anyone can see — 'moving planets and fixed stars' — and that the alternation of night and day is 'their following one another, and their trading length and shortness'. Al-Muyassar and al-Mukhtaṣar read it the same way: night follows day, and each grows longer and shorter in turn.",by:["ibnKathir","muyassar","mukhtasar"],cite:[e("tafsirIbnKathir","3:190","تعاقبهما وتقارضهما الطول والقصر"),e("tafsirMuyassar","3:190","واختلافهما طولا وقِصَرًا"),e("tafsirMukhtasar","3:190","وتفاوتهما طولًا وقِصَرًا")]},{ar:"وقال الطبري: جعل الله الليل والنهار «يختلفان ويعتقبان» على الناس، «تتصرفون في هذا لمعاشكم، وتسكنون في هذا راحة لأجسادكم». وقال السعدي إن أولي الألباب هم «الناظرون إليها بعقولهم لا بأبصارهم».",en:"Al-Ṭabarī: God made night and day 'differ and follow one another' — one to earn a living in, the other to rest the body. Al-Saʿdī: 'those of understanding' are the ones 'who look at them with their minds, not with their eyes'.",by:["tabari","saadi"],cite:[e("tafsirTabari","3:190","تتصرفون في هذا لمعاشكم، وتسكنون في هذا راحة لأجسادكم"),e("tafsirSaadi","3:190","الناظرون إليها بعقولهم لا بأبصارهم")]},{ar:"وفي صحيح البخاري (4569) عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم قعد في ثلث الليل الآخر، فنظر إلى السماء، ثم قرأ هذه الآية؛ أورده ابن كثير بإسناده، وذكره القرطبي والبغوي.",en:"In Ṣaḥīḥ al-Bukhārī (no. 4569), Ibn ʿAbbās reports that the Prophet (peace be upon him) sat up in the last third of the night, looked at the sky, and recited this verse. Ibn Kathīr quotes the report with its chain; al-Qurṭubī and al-Baghawī mention it too.",by:["ibnKathir","qurtubi","baghawi"],hadith:[{collection:"bukhari",no:[4569],from:{ar:"ابن عباس",en:"Ibn ʿAbbās"}}],cite:[e("bukhari","no. 4569 (Kitāb al-Tafsīr, Āl ʿImrān)","فَلَمَّا كَانَ ثُلُثُ اللَّيْلِ الآخِرُ قَعَدَ فَنَظَرَ إِلَى السَّمَاءِ"),e("tafsirIbnKathir","3:194 (the report with al-Bukhārī's chain)","فلما كان ثلث الليل الآخر قعد فنظر إلى السماء"),e("tafsirQurtubi","3:191 («وفي الصحيحين عن ابن عباس…»)"),e("tafsirBaghawi","3:190 (Ibn ʿAbbās's night with the Prophet)")]},{ar:"وعدّ ابن عثيمين من وجوه اختلافهما أن «الليل ظلمة والنهارَ نور»، وأنه «أحيانًا يطول الليل، وأحيانًا يطول النهار، وأحيانًا يتساويان».",en:"Ibn ʿUthaymīn counts among their differences that 'night is darkness and day is light', and that 'sometimes the night is longer, sometimes the day, and sometimes they are equal'.",by:["ibnUthaymin"],cite:[e("tafsirIbnUthaymin","Āl ʿImrān 190","أحيانًا يطول الليل، وأحيانًا يطول النهار، وأحيانًا يتساويان")]}],show:[{step:"scene",scene:"sky",note:{ar:"أفق المستخدم نفسه، الآن.",en:"The user's own horizon, now."}},{step:"timelapse",target:{horizon:"west"},span:"from an hour before sunset to an hour after the next sunrise",note:{ar:"يتحول النهار ليلاً فوق أفق المستخدم: تغرب الشمس، وتظهر النجوم، وتدور السماء، ثم يطلع الفجر.",en:"Day turns into night over the user's horizon: the Sun sets, the stars come out, the sky turns, and dawn breaks."}},{step:"interact",kind:"slider",note:{ar:"طول النهار في مكان المستخدم على مدار السنة، واليوم معلَّم عليه: أطول نهار وأقصره، واليومان اللذان يتقارب فيهما الليل والنهار (محسوب).",en:"The day's length at the user's place through the year, today marked: the longest and shortest days and the two days when night and day are nearly equal (computed)."}},{step:"scene",scene:"earth-from-space",note:{ar:"ابتعاد إلى الفضاء: الأرض تدور، ونصفها في ضوء الشمس.",en:"Pull back to space: the Earth turning, half of it in sunlight."}}],science:[{ar:"يتعاقب الليل والنهار لأن الأرض تدور حول محورها، فينتقل كل مكان عليها من الجانب المضيء بالشمس إلى الجانب المظلم ثم يعود؛ ولا يضيء الشمسُ من الأرض في كل لحظة إلا نصفها.",en:"Night follows day because the Earth turns on its axis, carrying every place from the sunlit side to the dark side and back; at any moment the Sun lights only half of the Earth.",cite:[e("nasaMoonPhases",'"That light always beams onto Earth and Moon from the direction of the Sun, illuminating half of our planet in its orbit"'),e("najmEngine","Astronomy Engine: the Sun's altitude over a place through a day")]},{ar:"ويطول النهار ويقصر على مدار السنة لأن محور الأرض مائل على مستوى مدارها حول الشمس بنحو ثلاث وعشرين درجة ونصف؛ ففي الكويت يبلغ أطول نهار نحو أربع عشرة ساعة في يونيو، وأقصره نحو عشر ساعات وربع في ديسمبر، ويتقارب الليل والنهار في مارس وسبتمبر.",en:"The day grows longer and shorter through the year because the Earth's axis is tilted about twenty-three and a half degrees to the plane of its orbit; in Kuwait the longest day lasts about fourteen hours in June and the shortest about ten and a quarter in December, and night and day are nearly equal in March and September.",computed:"obliquity 23.44° (Astronomy Engine e_tilt, 2026); Kuwait sunrise–sunset 21 Jun 2026 14 h 01 min, 21–22 Dec 10 h 15 min; heritage.ts equalDayNight(2026): 16 Mar and 27 Sep",cite:[e("najmEngine","WP-19 confirmation, items 1a–1c and 2b")]}],reflection:{by:"shaarawi",quote:"فاختلاف الليل والنهار ليس آية فقط ولكنه آيات لكثيرين … أنّ الفرد أعجز من أن يستنبط كل ما في الآيات، ولكن على كل واحد منكم أنتم البشر أن يستنبط آية",intro:{ar:"ومن تأملات الشيخ محمد متولي الشعراوي في هذه الآية:",en:"A reflection of Sheikh Muḥammad Mutawallī al-Shaʿrāwī on this verse:"},en:'(his words, rendered) "The alternation of night and day is not one sign but signs for many … no single person can draw out all that is in the signs, but each of you should draw out one."',cite:[e("sharawi","vol. 4 p. 1953 (Shāmila book 1083, p. 2131)","فاختلاف الليل والنهار ليس آية فقط ولكنه آيات لكثيرين")]}},{id:"moon-mansions",order:2,narration:"quran-moon-mansions",title:{ar:"القمر ومنازله",en:"The Moon and its stations"},recite:["36:39"],meaning:[{ar:"قال الطبري: قدّر الله القمر منازل «للنقصان بعد تناهيه وتمامه واستوائه»، حتى إذا كان «في آخر الشهر قبل استسراره» صار «في انحنائه وتقوّسه» كالعُرجون؛ والعرجون من عِذْق النخلة «من الموضع النابت في النخلة إلى موضع الشماريخ»، و«القديم هو اليابس».",en:"Al-Ṭabarī: God set the Moon's stations 'for its waning after it has reached its fullness', until, 'at the end of the month, before it hides', it is like the ʿurjūn 'in its bend and its curve' — the stalk of a date cluster 'from where it grows on the palm to the twigs'; and 'old' means dry.",by:["tabari"],cite:[e("tafsirTabari","36:39","فكذلك القمرُ إذا كان في آخر الشهر قبل استسراره، صار في انحنائه وتقوّسه نظير ذلك العرجون")]},{ar:"وقال ابن كثير: جعل الله القمر «يسير سيراً آخر يُستدل به على مضي الشهور»؛ يطلع أول الشهر «ضئيلاً قليل النور»، ثم يزداد نوراً «وإن كان مقتبساً من الشمس» حتى يتكامل نوره في الليلة الرابعة عشرة، ثم ينقص حتى يصير كالعرجون القديم.",en:"Ibn Kathīr: God gave the Moon 'a different course, by which the passing of the months is known'. It rises on the first night 'faint, with little light', then grows brighter — 'though its light is borrowed from the Sun' — until it is full on the fourteenth night, then wanes until it is like the old date stalk.",by:["ibnKathir"],cite:[e("tafsirIbnKathir","36:39","يطلع في أول ليلة من الشهر ضئيلا قليل النور")]},{ar:"وفي «التفسير الميسر»: يبدأ هلالاً ضئيلاً حتى يكمل قمراً مستديراً، ثم يرجع ضئيلاً «مثل عِذْق النخلة المتقوس في الرقة والانحناء والصفرة؛ لقدمه ويُبْسه»، وبمعناه «المختصر في التفسير»؛ وفي «الميسر في غريب القرآن» أن المنازل «ثمانيةٌ وعِشْرُونَ مَنزِلًا».",en:"Al-Muyassar: it begins as a faint crescent and grows into a round full moon, then shrinks back 'like the curved date stalk in its thinness, its bend and its yellowness, from age and dryness'; al-Mukhtaṣar says the same, and the King Fahd Complex's dictionary of rare Qur'anic words counts the stations: 'twenty-eight'.",by:["muyassar","mukhtasar","gharibMuyassar"],cite:[e("tafsirMuyassar","36:39","مثل عِذْق النخلة المتقوس في الرقة والانحناء والصفرة؛ لقدمه ويُبْسه"),e("tafsirMukhtasar","36:39","حتى يصير مثل عِذْق النخلة المُتَعرِّج المُنْدَرِس في رقته وانحنائه وصفرته وقِدَمه"),e("gharibMuyassar","36:39","وهي ثمانيةٌ وعِشْرُونَ مَنزِلًا")]},{ar:"وعدّ القرطبي المنازل الثماني والعشرين بأسمائها، من الشَّرَطين إلى بطن الحوت، «ينزل القمر كل ليلة منها بمنزل»؛ وقال ابن عثيمين: يبقى القمر مستتراً ليلة إن كان الشهر تسعاً وعشرين، وليلتين إن كان ثلاثين، «تسمَّى هاتانِ الليلتانِ ليالي الاستسرار».",en:"Al-Qurṭubī lists the twenty-eight stations by name, from al-Sharaṭān to Baṭn al-Ḥūt, 'the Moon stopping at one of them each night'; Ibn ʿUthaymīn adds that it stays hidden one night when the month has twenty-nine days and two when it has thirty — 'these two nights are called the nights of hiding'.",by:["qurtubi","ibnUthaymin"],cite:[e("tafsirQurtubi","36:39","ينزل القمر كل ليلة منها بمنزل"),e("tafsirIbnUthaymin","Yā-Sīn 39","تسمَّى هاتانِ الليلتانِ ليالي الاستسرار")]}],show:[{step:"timelapse",target:{body:"moon"},span:"one lunar month, night by night at the same hour (after sunset for the waxing half, before dawn for the waning half)",note:{ar:"القمر يتنقّل كل ليلة إلى منزلة، واسم المنزلة على الشاشة (بيانات منازل القمر في «نجم»)، من الهلال إلى البدر ثم إلى الهلال الأخير.",en:"The Moon moves on a station each night, the station named on screen (Najm's lunar-mansion data), from crescent to full and back to the last crescent."}},{step:"fly",target:{body:"moon"},note:{ar:"هندسة الهلال المتناقص قبيل شروق الشمس في جهة الشرق، مكبَّراً بجانب رسم توضيحي لعرجون نخلة قديم. معيار الرؤية الصباحي غير متحقق؛ هذه هندسة القمر قبل الشروق وليست وعداً برؤيته.",en:"The geometry of a waning crescent before sunrise in the east, zoomed in beside an illustration of an old date stalk. The morning visibility criterion is unverified: this shows lunar geometry before sunrise and does not promise a sighting."}},{step:"interact",kind:"slider",note:{ar:"ليلة بليلة، بإصبع المستخدم.",en:"Night by night, under the user's finger."}}],science:[{ar:"يدور القمر حول الأرض دورة كاملة بين النجوم في نحو 27.3 يوماً، فيتقدم كل ليلة نحو ثلاث عشرة درجة نحو الشرق، أي نحو منزلة؛ أما الشهر من محاق إلى محاق فنحو 29.5 يوماً، لأن الأرض تكون قد تقدمت في مدارها حول الشمس.",en:"The Moon goes once round the Earth against the stars in about 27.3 days, moving about thirteen degrees east each night — roughly one station; from new Moon to new Moon takes about 29.5 days, because meanwhile the Earth has moved on along its orbit around the Sun.",facts:[{body:"moon",key:"orbitEarth",said:27.3},{body:"moon",key:"synodicMonth",said:29.5}],computed:"360° / 27.32 d = 13.2° a day",cite:[e("najmDetails","BODY_FACTS.moon: orbitEarth, synodicMonth"),e("najmEngine","the Moon's daily motion")]},{ar:"ونصف القمر المواجه للشمس مضيء دائماً، ويتغير ما نراه من هذا النصف مع مسير القمر في مداره؛ والهلال المتناقص في آخر الشهر يطلع قبيل شروق الشمس، ثم يغيب في ضوئها حتى يظهر الهلال الجديد بعد الغروب.",en:"The half of the Moon facing the Sun is always lit, and how much of that half we see changes as the Moon moves along its orbit; the waning crescent at the end of the month rises shortly before sunrise, then vanishes in the Sun's glare until the new crescent appears after sunset.",cite:[e("nasaMoonPhases",'"The Sun always illuminates half of the Moon while the other half remains dark, but how much we are able to see of that illuminated half changes as the Moon travels through its orbit."'),e("nasaMoonPhases",'"The waning crescent Moon rises in the very early morning, before sunrise"')]},{ar:"رؤية الهلال تتأثر بموضع القمر والشمس وصفاء الجو وخبرة الراصد. معيار عودة المستعمل هنا للهلال المسائي؛ لم نتحقق من معيار صباحي، لذلك لا نحدد آخر صباح يرى فيه الهلال المتناقص، ولا عدد الليالي التي يغيب فيها عن العين.",en:"Crescent visibility depends on the positions of the Moon and Sun, atmospheric clarity and the observer. The Odeh criterion used here is for the evening crescent. A morning criterion has not been verified, so we do not identify the last visible waning crescent or count its invisible nights.",cite:[e("najmEngine","quranJourneyMoon.ts: morning visibility is unverified; no mirrored evening criterion is applied")]}]},{id:"shira",order:3,narration:"quran-shira",title:{ar:"الشِّعرى",en:"Sirius"},recite:["53:49"],meaning:[{ar:"قال الطبري: الشِّعرى هي النجم المسمّى بهذا الاسم، «وهو نجم كان بعض أهل الجاهلية يعبده من دون الله»؛ وروى عن مجاهد أنه «الكوكب الذي خَلْف الجوزاء، كانوا يعبدونه»، وعن ابن زيد في معنى الآية: «تعبدون هذه وتتركون ربها؟ اعبدوا ربها».",en:"Al-Ṭabarī: al-Shiʿrā is 'the star of that name, which some in the time before Islam worshipped instead of God'. He reports Mujāhid — 'the star behind al-Jawzāʾ [Orion]; they worshipped it' — and Ibn Zayd on the verse's point: 'You worship this and leave its Lord? Worship its Lord.'",by:["tabari"],cite:[e("tafsirTabari","53:49","تعبدون هذه وتتركون ربها؟ اعبدوا ربها")]},{ar:"وقال ابن كثير: هو «هذا النجم الوقاد الذي يقال له: مرزم الجوزاء»، و«كانت طائفة من العرب يعبدونه». وقال السعدي: خصّها الله بالذكر «وإن كان رب كل شيء»، لأنها مما عُبد في الجاهلية، فأخبر أن ما يعبده المشركون «مربوب مدبر مخلوق»؛ ونحوه في «التفسير الميسر».",en:"Ibn Kathīr: it is 'this blazing star called Mirzam al-Jawzāʾ, which a group of the Arabs worshipped'. Al-Saʿdī: God named it 'though He is the Lord of everything', because it had been worshipped, to teach that what idolaters worship is 'ruled, ordered and created'; al-Muyassar says the same.",by:["ibnKathir","saadi","muyassar"],cite:[e("tafsirIbnKathir","53:49","هو هذا النجم الوقاد الذي يقال له"),e("tafsirSaadi","53:49","مربوب مدبر مخلوق"),e("tafsirMuyassar","53:49","وهو نجم مضيء، كان بعض أهل الجاهلية يعبدونه من دون الله")]},{ar:"وقال القرطبي: الشعرى «الكوكب المضيء الذي يطلع بعد الجوزاء، وطلوعه في شدة الحر».",en:"Al-Qurṭubī: al-Shiʿrā is 'the bright star that rises after al-Jawzāʾ, and its rising comes in the fiercest heat'.",by:["qurtubi"],cite:[e("tafsirQurtubi","53:49","الكوكب المضيء الذي يطلع بعد الجوزاء ، وطلوعه في شدة الحر")]},{ar:"وحكى القرطبي ما «تزعم العرب» من أن الشِّعريين أختا سُهيل، وذكر البغوي أن المجرّة بينهما، وأن الغُمَيصاء سُمّيت بذلك «لأنها أخفى من الأخرى».",en:"Al-Qurṭubī reports what 'the Arabs claim' — that the two Shiʿrās are Suhail's sisters; al-Baghawī adds that the Milky Way lies between them, and that al-Ghumayṣāʾ is so named 'because she is the fainter of the two'.",by:["qurtubi","baghawi"],legend:!0,cite:[e("tafsirQurtubi","53:49","وتزعم العرب أنهما أختا سهيل"),e("tafsirBaghawi","53:49","سميت بذلك لأنها أخفى من الأخرى")]}],show:[{step:"fly",target:{hip:32349},note:{ar:"الشعرى في سماء المستخدم الآن: فوق الأفق، أو تحته مع جهة شروقها وموعده.",en:"Sirius in the user's sky now: above the horizon, or below it with where and when it rises."}},{step:"overlay",note:{ar:"خط من النظام (حزام الجبار) نزولاً إلى الشعرى، والغُمَيصاء (الشعرى الشامية) على الجانب الآخر من المجرة.",en:"A line from al-Niẓām (Orion's belt) down to Sirius, and al-Ghumayṣāʾ (Procyon) across the Milky Way."}},{step:"overlay",note:{ar:"محسوب: أول ظهورها فجراً في مكة في عهد النبي صلى الله عليه وسلم، وفي مدينة المستخدم هذا العام.",en:"Computed: its first dawn appearance in Mecca in the Prophet's time, and in the user's city this year."}}],science:[{ar:"الشعرى ألمع نجوم الليل (والزهرة والمشتري والقمر أشد منها لمعاناً)، على بعد نحو 8.6 سنة ضوئية، وتشع نحو خمسة وعشرين ضعف ما تشعه الشمس، ويدور حولها نجم صغير خافت من الأقزام البيضاء لا يُرى بالعين.",en:"Sirius is the brightest star of the night sky (Venus, Jupiter and the Moon outshine it), about 8.6 light-years away; it gives out about twenty-five times the Sun's light, and a small, faint white dwarf, invisible to the eye, circles it.",facts:[{hip:32349,key:"distance",said:8.6},{hip:32349,key:"lumStar",said:25},{hip:32349,key:"components",said:2}],cite:[e("najmDetails","STAR_DETAILS HIP 32349: distance, lumStar, components"),e("catalog","HIP 32349, the brightest star in the catalogue")]},{ar:"وبحساب «نجم» لأول ظهورها فجراً (نموذج شيفر، في هواء خليجي معتاد): كان ذلك في مكة والمدينة زمن النبوة نحو منتصف يوليو بالتقويم اليولياني، بعد الانقلاب الصيفي بنحو ثلاثة أسابيع، في قلب الصيف؛ وهو في الكويت اليوم في أوائل أغسطس. والتاريخ يتقدم أو يتأخر أياماً بحسب صفاء الجو والأفق.",en:"Najm's computation of its first appearance at dawn (Schaefer's model, typical Gulf air): in Mecca and Medina in the Prophet's time it was around the middle of July in the Julian calendar, about three weeks after the June solstice — high summer; in Kuwait today it is early August. The date moves by some days with the clearness of the air and the horizon.",computed:"heritage.ts siriusHeliacal: Mecca AD 630 11–13 Jul (Julian), Medina 14–15 Jul; Kuwait 2026 2–4 Aug (k 0.20–0.30)",cite:[e("heritageCalc","siriusHeliacal (the WP-12b method)"),e("najmEngine","WP-19 confirmation, item 4c")]}]},{id:"khunnas",order:4,narration:"quran-khunnas",title:{ar:"الخُنَّس",en:"The ones that turn back"},recite:["81:15","81:16"],meaning:[{ar:"اختلف المفسرون في «الخُنَّس الجَوار الكُنَّس»: فروى الطبري عن علي رضي الله عنه أنها «النجوم تخنس بالنهار، وتكنس بالليل»، وذكر قولاً أنها «النجوم الدراريّ الخمسة تخنِس في مجراها فترجع»: زحل والمشتري والمريخ والزهرة وعطارد؛ وروى عن ابن مسعود أنها بقر الوحش، وعن ابن عباس في رواية أنها الظباء.",en:"The exegetes differ on 'al-khunnas, al-jawār al-kunnas'. Al-Ṭabarī reports ʿAlī: 'the stars that recede by day and hide by night'; he records a view that they are 'the five bright stars that recede in their course and turn back' — Saturn, Jupiter, Mars, Venus and Mercury; and he reports Ibn Masʿūd: wild cattle, and Ibn ʿAbbās in one report: gazelles.",by:["tabari"],cite:[e("tafsirTabari","81:15–16","هي النجوم الدراريّ الخمسة تخنِس في مجراها فترجع وتكنس")]},{ar:"ثم رجّح الطبري أن الآية تعمّ «كلّ ما كانت صفته الخنوس أحيانا والجري أخرى، والكنوس بآنات»، نجماً كان أو ظبياً أو بقراً؛ وذكر ابن كثير توقّفه وقوله: «ويحتمل أن يكون الجميع مرادا».",en:"Al-Ṭabarī's own judgement: the verse covers 'everything whose way is to recede at times, run at others, and hide at times' — star, gazelle or wild cattle; Ibn Kathīr notes that he left it open: 'all of them may be meant'.",by:["tabari","ibnKathir"],cite:[e("tafsirTabari","81:16 (his ruling)","كلّ ما كانت صفته الخنوس أحيانا والجري أخرى، والكنوس بآنات"),e("tafsirIbnKathir","81:15","ويحتمل أن يكون الجميع مرادا")]},{ar:"وقال القرطبي: هي الكواكب الخمسة «فيما ذكر أهل التفسير»، وسُمّيت خُنَّساً «لتأخرها، لأنها الكواكب المتحيرة التي ترجع وتستقيم»؛ وقال البغوي: «وأصل الخنوس: الرجوع إلى وراء»، والكنوس «أن تأوي إلى مكانسها» كما تأوي الوحوش.",en:"Al-Qurṭubī: they are the five planets 'as the exegetes mention', called khunnas 'for their lagging, because they are the wandering stars that turn back and then go straight'. Al-Baghawī: 'the root of khunūs is going back', and kunūs is 'to withdraw into their lairs', as wild animals do.",by:["qurtubi","baghawi"],cite:[e("tafsirQurtubi","81:15–16","سميت خنسا لتأخرها ، لأنها الكواكب المتحيرة التي ترجع وتستقيم"),e("tafsirBaghawi","81:16","وأصل الخنوس : الرجوع إلى وراء")]},{ar:"وقال السعدي: هي التي «تتأخر عن سير الكواكب المعتاد إلى جهة المشرق»، وعدّ معها الشمس والقمر على ما كان يُعدّ قديماً من «النجوم السبعة السيارة»؛ وفي «المختصر في التفسير»: أقسم الله «بالنجوم الخفية قبل بزوغها في الليل»، «الجاريات في أفلاكها».",en:"Al-Saʿdī: they are the ones that 'lag behind the ordinary course of the stars, toward the east', and he counts the Sun and the Moon with them, following the old reckoning of 'the seven moving stars'. Al-Mukhtaṣar: God swears 'by the stars hidden before they appear at night', 'running in their orbits'.",by:["saadi","mukhtasar"],cite:[e("tafsirSaadi","81:15","تتأخر عن سير الكواكب المعتاد إلى جهة المشرق"),e("tafsirMukhtasar","81:15–16","أقسم الله بالنجوم الخفية قبل بزوغها في الليل")]},{ar:"وفي صحيح مسلم (475) عن عمرو بن حريث رضي الله عنه أنه صلّى خلف النبي صلى الله عليه وسلم الفجر فسمعه يقرأ بهاتين الآيتين؛ وأورده ابن كثير.",en:"In Ṣaḥīḥ Muslim (no. 475), ʿAmr ibn Ḥurayth reports praying the dawn prayer behind the Prophet (peace be upon him) and hearing him recite these two verses; Ibn Kathīr cites it.",by:["ibnKathir"],hadith:[{collection:"muslim",no:[475],from:{ar:"عمرو بن حريث",en:"ʿAmr ibn Ḥurayth"}}],cite:[e("muslim","no. 475 (Kitāb al-Ṣalāt)","صليت خلف النبي صلى الله عليه وسلم الفجر"),e("tafsirIbnKathir","81:15 (Muslim's report)")]}],show:[{step:"timelapse",target:{body:"mars"},span:"about seven months around the next opposition, one frame a day against the stars",note:{ar:"المريخ يسير نحو الشرق، ثم يقف، ثم يرجع نحو الغرب نحو 81 يوماً في دورة 2027، ثم يقف ويعود إلى سيره؛ مساره المؤرّخ مرسوم على السماء (محسوب).",en:"Mars moves east, stops, goes back west for about 81 days in the 2027 cycle, stops, and goes east again. Its dated path is drawn on the sky (computed)."}},{step:"scene",scene:"solar-system",note:{ar:"من فوق المجموعة الشمسية: الأرض في مدارها الأقرب والأسرع تلحق بالمريخ وتسبقه، فيبدو من الأرض كأنه يرجع.",en:"Above the Solar System: the Earth, on its faster inner orbit, catches up with Mars and passes it, so from Earth Mars seems to go back."}},{step:"overlay",note:{ar:"الكواكب التي تُرى بالعين الآن: أيها فوق الأفق، وأيها غائب في ضوء الشمس.",en:"The naked-eye planets now: which are up, and which are hidden in the Sun's glare."}}],science:[{ar:"تسير الكواكب بين النجوم عادةً نحو الشرق، لكن الكوكب يبدو أحياناً كأنه يقف ثم يرجع نحو الغرب أسابيع، ثم يقف ويعود إلى سيره. وهذه الحركة التراجعية ظاهرية: تحدث للمريخ حين تلحق به الأرض وتتجاوزه، لأنها تدور حول الشمس في مدار أقرب وأسرع، مرة كل سنتين وشهرين تقريباً. دامت فترات تراجعه المحسوبة بين 2016 و2041 نحو 61 إلى 81 يوماً؛ وتستغرق دورة 2027 نحو 81 يوماً.",en:"The planets usually move east among the stars, but a planet sometimes seems to stop, go back west for weeks, then stop and go on again. This backward ('retrograde') motion is apparent: it happens to Mars when the Earth, on its closer, faster orbit, catches up with it and passes it — about once every two years and two months. The computed 2016–2041 retrograde spells last about 61–81 days; the 2027 cycle lasts about 81 days.",computed:"synodic period 779.94 d (oppositions 2020–2099: 764–811 d); retrograde spells 2016–2041: 61–81 d; next: stations 10 Jan and 1 Apr 2027, opposition 19 Feb 2027, all in Leo",cite:[e("najmEngine","WP-19 confirmation, items 5a–5d (events.ts oppositions; JPL Horizons check)")]},{ar:"والكواكب الخمسة التي تُرى بالعين كلها تبدو كأنها ترجع بين النجوم حيناً، لكن عطارد والزهرة يفعلان ذلك قرب الشمس في وهجها؛ وكل منها يغيب عن الأنظار أسابيع حين يقترب من الشمس في السماء.",en:"All five planets seen with the eye seem to go backward among the stars at times, though Mercury and Venus do it close to the Sun, in its glare; and each disappears for weeks when it comes close to the Sun in the sky.",computed:"2026–2029 retrograde spells: Mercury 20–24 d and Venus 42–43 d (within 7° of the Sun), Mars 80–81 d, Jupiter 121–123 d, Saturn 136–137 d",cite:[e("najmEngine","WP-19 confirmation, item 5e")]}]},{id:"guiding-stars",order:5,narration:"quran-guiding-stars",title:{ar:"نجوم يُهتدى بها",en:"Stars to steer by"},recite:["6:97"],meaning:[{ar:"قال الطبري: جعل الله لكم النجوم «أدلةً في البر والبحر إذا ضللتم الطريق»، تستدلّون بها ليلاً على المحجّة؛ «وعنى بالظلمات، ظلمة الليل، وظلمة الخطأ والضلال، وظلمة الأرض أو الماء».",en:"Al-Ṭabarī: God made the stars 'guides on land and sea when you lose the way', to find the road by night; 'by the darknesses He meant the darkness of night, the darkness of error and straying, and the darkness of land or water'.",by:["tabari"],cite:[e("tafsirTabari","6:97","وعنى بالظلمات، ظلمة الليل, وظلمة الخطأ والضلال, وظلمة الأرض أو الماء")]},{ar:"وقال السعدي: منها «نجوم لا تزال ترى، ولا تسير عن محلها»، ومنها «ما هو مستمر السير، يعرف سيرَه أهل المعرفة بذلك، ويعرفون به الجهات والأوقات»؛ وقال: «ودلت هذه الآية ونحوها، على مشروعية تعلم سير الكواكب ومحالّها».",en:"Al-Saʿdī: some stars 'are always seen and never leave their place', and some 'keep moving; those who know their courses tell directions and times by them'. He adds: 'this verse and its like show that learning the courses of the stars and their places is legitimate'.",by:["saadi"],cite:[e("tafsirSaadi","6:97","ودلت هذه الآية ونحوها، على مشروعية تعلم سير الكواكب ومحالّها")]},{ar:"ونقل ابن كثير عن بعض السلف: «من اعتقد في هذه النجوم غير ثلاث فقد أخطأ وكذب على الله: أن الله جعلها زينة للسماء، ورجوما للشياطين، ويهتدى بها في ظلمات البر والبحر». وفي «المختصر في التفسير»: لتهتدوا بها «في أسفاركم إذا اشتبهت عليكم الطرق في البر والبحر»، ونحوه في «التفسير الميسر».",en:"Ibn Kathīr quotes one of the early Muslims: 'Whoever believes anything about these stars but three things has erred and lied about God: He made them an adornment of the sky, missiles against the devils, and guides in the darkness of land and sea.' Al-Mukhtaṣar: to steer by them 'on your journeys, when the roads of land and sea are unclear to you'; al-Muyassar likewise.",by:["ibnKathir","mukhtasar","muyassar"],cite:[e("tafsirIbnKathir","6:97","من اعتقد في هذه النجوم غير ثلاث فقد أخطأ وكذب على الله"),e("tafsirMukhtasar","6:97","في أسفاركم إذا اشتبهت عليكم الطرق في البر والبحر"),e("tafsirMuyassar","6:97","تعرفون بها الطرق ليلا إذا ضللتم بسبب الظلمة الشديدة في البر والبحر")]},{ar:"وفي سورة النحل ذكرُ النجم الذي يهتدي به الناس ليلاً (النحل: 16)، قال الطبري: «هو الجدي والفرقدان، لأن بها اهتداء السفر دون غيرها من النجوم» — يعني الجُدَيّ، نجم القطب — ونقل القرطبي القول نفسه عن الفراء.",en:"Sūrat al-Naḥl (16:16) speaks of the star people steer by at night; al-Ṭabarī says it is 'al-Judayy and al-Farqadān, for travellers steer by them rather than by any other stars' — al-Judayy being the Pole Star — and al-Qurṭubī reports the same from al-Farrāʾ.",by:["tabari","qurtubi"],mentions:["16:16"],cite:[e("tafsirTabari","16:16","الجدي والفرقدان، لأن بها اهتداء السفر دون غيرها من النجوم"),e("tafsirQurtubi","16:16","فقال الفراء : الجدي والفرقدان")]}],show:[{step:"fly",target:{hip:11767},note:{ar:"إلى الشمال، إلى الجُدَيّ: ارتفاعه فوق الأفق يكاد يساوي خط عرض المستخدم (محسوب).",en:"North, to al-Judayy (Polaris): its height above the horizon nearly equals the user's latitude (computed)."}},{step:"timelapse",target:{horizon:"north"},span:"six hours",note:{ar:"السماء تدور حول الجُدَيّ وهو يكاد لا يتحرك.",en:"The sky turns around al-Judayy while it barely moves."}},{step:"interact",kind:"aim",target:{hip:11767},note:{ar:"اعرف الشمال بالجُدَيّ.",en:"Find north by al-Judayy."}},{step:"fly",target:{hip:30438},note:{ar:"سُهيل منخفضاً في الجنوب حين يكون فوق أفق المستخدم، وإلا فموعد عودته.",en:"Suhail (Canopus) low in the south when it is above the user's horizon; otherwise, when it returns."}}],science:[{ar:"الجُدَيّ (نجم القطب) قريب جداً من القطب الشمالي للسماء، على أقل من درجة منه، فيبدو ثابتاً والسماء تدور حوله؛ وارتفاعه فوق الأفق يساوي تقريباً خط عرض الراصد: نحو تسع وعشرين درجة في الكويت.",en:"Al-Judayy (Polaris) lies very close to the north pole of the sky, less than a degree from it, so it seems fixed while the sky turns around it; its height above the horizon is about the observer's latitude — about twenty-nine degrees in Kuwait.",computed:"Polaris 0.62–0.63° from the pole of date through 2026; altitude in Kuwait 28.8–30.0°, never more than 0.72° from true north",cite:[e("najmEngine","WP-19 confirmation, items 6a–6b")]},{ar:"ولم يكن الجُدَيّ في القرون الأولى بهذا القرب من القطب: كان زمن النبوة على نحو ثماني درجات منه، ثم أخذ يقترب ببطء مع تغيّر اتجاه محور الأرض.",en:"In the early centuries al-Judayy was not this close to the pole: in the Prophet's time it was about eight degrees from it, and it has been creeping closer as the direction of the Earth's axis slowly changes.",computed:"Polaris from the pole: 8.3° in AD 630, 7.0° in 850, 4.7° in 1273, 0.62° in 2026 (precession, Astronomy Engine)",cite:[e("najmEngine","WP-19 confirmation, item 6c")]},{ar:"ويبعد الجُدَيّ عنا أكثر من أربعمئة سنة ضوئية (تختلف القياسات بين نحو 430 ونحو 520)، وسُهيل نحو 310.",en:"Al-Judayy is more than four hundred light-years away (measurements range from about 430 to about 520), and Suhail about 310.",facts:[{catalogDist:30438,said:310}],cite:[e("najmDetails","STAR_DETAILS HIP 11767: distance 447 ly, with its note that the sources differ (Hipparcos 433, HST 521)"),e("catalog","HIP 11767 dist (433 ly); HIP 30438 dist (309 ly)")]}],reflection:{by:"shaarawi",quote:"يقول الواحد منهم للآخر: اجعل النجم الفلاني أمام عينيك، وسر فوق الحي الفلاني. واجعل النجم الفلاني عن يسارك وامش تجد كذا",intro:{ar:"ويصف الشيخ الشعراوي كيف كان العرب يهتدون بالنجوم:",en:"Sheikh al-Shaʿrāwī describes how the Arabs found their way by the stars:"},en:'(his words, rendered) "One of them would say to another: keep such-and-such a star before your eyes and travel over such-and-such a tribe; keep such-and-such a star on your left and walk, and you will find such-and-such."',cite:[e("sharawi","vol. 6 p. 3814 (Shāmila book 1083, p. 4291)","اجعل النجم الفلاني أمام عينيك")]}},{id:"crescents",order:6,narration:"quran-crescents",title:{ar:"الأهلّة",en:"The crescents"},recite:["2:189"],meaning:[{ar:"اختلف المفسرون فيما سألوا عنه: فذكر الطبري أن النبي صلى الله عليه وسلم «سُئل عن زيادة الأهلة ونقصانها واختلاف أحوالها»، وروى عن قتادة أنهم سألوا: «لم جُعلت هذه الأهلة؟»؛ وقال ابن عثيمين: سألوه «عن الحكمة من الأهلة» بدليل الجواب، ولم يثبت بنص صحيح أنهم سألوا عن سبب نموّ الهلال.",en:"The exegetes differ on what was asked. Al-Ṭabarī reports that the Prophet (peace be upon him) 'was asked about the crescents' growing and shrinking and their changing states', and, from Qatāda, that they asked 'why were these crescents made?'; Ibn ʿUthaymīn holds that they asked 'about the wisdom of the crescents', as the answer shows — no sound report says they asked why the crescent grows.",by:["tabari","ibnUthaymin"],cite:[e("tafsirTabari","2:189","سُئل عن زيادة الأهلة ونقصانها واختلاف أحوالها"),e("tafsirIbnUthaymin","al-Baqara 189","سألوه عن الحكمة من الأهلة")]},{ar:"فأجابهم الله بأنها مواقيت: قال الطبري: يرقبون «بزيادتها ونقصانها ومحاقِها واستسرارها» أوقات ديونهم وصومهم وفطرهم وعِدّة نسائهم وحجّهم؛ ونقل ابن كثير عن ابن عباس: «يعلمون بها حل دينهم، وعدة نسائهم، ووقت حجهم».",en:"The answer: they are times to keep. Al-Ṭabarī: people watch, 'by their growing, waning, vanishing and hiding', for when debts fall due, for fasting and its end, for waiting periods and for the pilgrimage; Ibn Kathīr quotes Ibn ʿAbbās: 'by them they know when their debts fall due, their wives' waiting periods, and the time of their pilgrimage'.",by:["tabari","ibnKathir"],cite:[e("tafsirTabari","2:189","ترقبون بزيادتها ونقصانها ومحاقِها واستسرارها"),e("tafsirIbnKathir","2:189","يعلمون بها حل دينهم ، وعدة نسائهم ، ووقت حجهم")]},{ar:"وقال السعدي: جعله الله حساباً «يعرفه كل أحد، من صغير، وكبير، وعالم، وجاهل»، ولو كان الحساب بالسنة الشمسية «لم يعرفه إلا النادر من الناس». وقال ابن عثيمين: الهلال «علامة حسية ظاهرة»، جعل الله به الأشهر «مواقيت للناس، للناس عموما، لا للمسلمين فقط».",en:"Al-Saʿdī: God made it a reckoning 'that everyone knows — young and old, learned and unlearned'; reckoned by the solar year, 'only a few people would know it'. Ibn ʿUthaymīn: the crescent is 'a sign plain to the senses', by which God made the months 'times for people — for all people, not for Muslims alone'.",by:["saadi","ibnUthaymin"],cite:[e("tafsirSaadi","2:189","فلو كان الحساب بالسنة الشمسية, لم يعرفه إلا النادر من الناس"),e("tafsirIbnUthaymin","al-Baqara 189","فهو علامة حسية ظاهرة")]},{ar:"وقال البغوي: سُمّي هلالاً «لأن الناس يرفعون أصواتهم بالذكر عند رؤيته».",en:"Al-Baghawī: it is called hilāl 'because people raise their voices in remembrance when they see it'.",by:["baghawi"],cite:[e("tafsirBaghawi","2:189","سمي هلالا لأن الناس يرفعون أصواتهم بالذكر عند رؤيته")]},{ar:"وفي بقية الآية روى البخاري (4512) عن البراء رضي الله عنه أنهم كانوا إذا أحرموا في الجاهلية أتوا البيت من ظهره، فنزلت؛ أورده ابن كثير والطبري، وفي «التفسير الميسر»: ليس الخير ذلك، «ولكن الخير هو فِعْلُ مَنِ اتقى الله».",en:"On the rest of the verse, al-Bukhārī (no. 4512) reports al-Barāʾ: before Islam, people who had entered the pilgrim state came into their houses from the back, and the verse was revealed; Ibn Kathīr and al-Ṭabarī cite it, and al-Muyassar explains: that is not righteousness — 'righteousness is the deed of one who fears God'.",by:["ibnKathir","tabari","muyassar"],hadith:[{collection:"bukhari",no:[4512],from:{ar:"البراء بن عازب",en:"al-Barāʾ ibn ʿĀzib"}}],cite:[e("bukhari","no. 4512 (Kitāb al-Tafsīr, al-Baqara)","كَانُوا إِذَا أَحْرَمُوا فِي الْجَاهِلِيَّةِ أَتَوُا الْبَيْتَ مِنْ ظَهْرِهِ"),e("tafsirIbnKathir","2:189 (al-Bukhārī's report)"),e("tafsirTabari","2:189 (al-Barāʾ's report)"),e("tafsirMuyassar","2:189","ولكن الخير هو فِعْلُ مَنِ اتقى الله")]}],show:[{step:"fly",target:{horizon:"west"},note:{ar:"الأفق الغربي بعد الغروب في المساء القادم الذي قد يُرى فيه الهلال، وتوقُّع الرؤية لمكان المستخدم بمعياري عودة ويالوب تحت علامة «توقع فلكي»؛ ولا تُعلن «نجم» دخول الشهر.",en:"The western horizon after sunset on the next evening the crescent may be seen, with the visibility prediction for the user's place by Odeh's and Yallop's criteria under the label 'astronomical prediction'; Najm never announces the start of a month."}},{step:"timelapse",target:{body:"moon"},span:"from sunset to moonset, then the following evenings",note:{ar:"الهلال يغرب بعد الشمس بقليل، ثم يكبر ويعلو مساءً بعد مساء.",en:"The crescent sets soon after the Sun, then grows and stands higher evening after evening."}},{step:"interact",kind:"tap",note:{ar:"فتح صفحة ترقّب الهلال.",en:"Open the crescent watch."}}],science:[{ar:"عند الاقتران يكون القمر بين الأرض والشمس فلا يُرى؛ ثم يبتعد عن الشمس في السماء قليلاً كل يوم، فيظهر بعد غروبها هلالاً رقيقاً منخفضاً في الغرب، يغرب بعدها بقليل. وإمكان رؤيته يتوقف على بُعده عن الشمس وارتفاعه وصفاء الجو، وتتوقعه معايير فلكية منها معيارا عودة ويالوب.",en:"At conjunction the Moon lies between the Earth and the Sun and cannot be seen; then it moves a little farther from the Sun in the sky each day, and appears after sunset as a thin crescent low in the west, setting soon after. Whether it can be seen depends on its distance from the Sun, its height and the clearness of the air; astronomical criteria such as Odeh's and Yallop's predict it.",cite:[e("nasaMoonPhases",'"The new Moon rises and sets with the Sun, but is not visible in the daytime sky because the night side (unlit side) of the Moon faces towards Earth."'),e("najmEngine","src/engine/hilal.ts (Odeh 2004; Yallop 1997)")]},{ar:"والشهر القمري تسعة وعشرون يوماً أو ثلاثون، ومتوسطه نحو 29.5 يوماً؛ فاثنا عشر شهراً قمرياً نحو 354 يوماً، أقصر من السنة الشمسية بنحو أحد عشر يوماً، ولذلك يمرّ رمضان والحج على فصول السنة كلها في نحو ثلاث وثلاثين سنة.",en:"A lunar month has twenty-nine or thirty days, about 29.5 on average; twelve lunar months make about 354 days, some eleven days shorter than the solar year, so Ramadan and the Hajj move through all the seasons in about thirty-three years.",facts:[{body:"moon",key:"synodicMonth",said:29.5}],computed:"12 × 29.530589 d = 354.367 d; 365.2422 − 354.367 = 10.875 d; a full cycle 33.6 lunar = 32.6 solar years",cite:[e("najmDetails","BODY_FACTS.moon: synodicMonth"),e("najmEngine","WP-19 confirmation, item 7")]}],reflection:{by:"shaarawi",quote:"… فيأتي التكليف في كل جو وطقس من أجواء السنة، فلا تصوم رمضان في صيف دائم، ولا في شتاء دائم، ولكن يُقَلِّبُ الله مواعيد العبادات على سائر أيام السنة",intro:{ar:"ويتأمل الشيخ الشعراوي حكمة الحساب بالقمر:",en:"Sheikh al-Shaʿrāwī reflects on the wisdom of reckoning by the Moon:"},en:'(his words, rendered) "… so the duty comes in every weather of the year: you do not fast Ramadan in an endless summer, nor in an endless winter; God turns the times of worship through all the days of the year."',cite:[e("sharawi","vol. 2 p. 812 (Shāmila book 1083, p. 786)","فلا تصوم رمضان في صيف دائم، ولا في شتاء دائم")]}},{id:"light",order:7,narration:"quran-light",title:{ar:"ضياءٌ ونور",en:"Radiance and light"},recite:["10:5"],meaning:[{ar:"قال ابن كثير: جعل الله «الشعاع الصادر عن جرم الشمس ضياء وشعاع القمر نورا، هذا فن وهذا فن آخر، ففاوت بينهما لئلا يشتبها»، وجعل سلطان الشمس بالنهار وسلطان القمر بالليل؛ «فبالشمس تعرف الأيام، وبسير القمر تعرف الشهور والأعوام».",en:"Ibn Kathīr: God made 'the rays that come from the body of the Sun a radiance (ḍiyāʾ) and the Moon's rays a light (nūr) — one kind and another kind; He made them differ so they would not be alike'; the Sun rules the day and the Moon the night, and 'by the Sun the days are known, and by the Moon's course the months and years'.",by:["ibnKathir"],cite:[e("tafsirIbnKathir","10:5","هذا فن وهذا فن آخر ، ففاوت بينهما لئلا يشتبها")]},{ar:"وقال ابن كثير في تفسير سورة يس إن القمر يزداد نوراً «وإن كان مقتبسا من الشمس»، وقال ابن عثيمين: «لأن نور القمر مستمدٌّ من نور الشمس، هو نفسه ليس به إضاءة، جِرْمٌ مُظلم».",en:"Ibn Kathīr, on Sūrat Yā-Sīn: the Moon grows brighter 'though its light is borrowed from the Sun'; Ibn ʿUthaymīn: 'the Moon's light is drawn from the light of the Sun; it has no light of its own — a dark body'.",by:["ibnKathir","ibnUthaymin"],cite:[e("tafsirIbnKathir","36:39","وإن كان مقتبسا من الشمس"),e("tafsirIbnUthaymin","Yā-Sīn 39","لأن نور القمر مستمدٌّ من نور الشمس، هو نفسه ليس به إضاءة، جِرْمٌ مُظلم")]},{ar:"وقال الطبري: «هو الذي أضاء الشمسَ وأنار القمر»، وقدّره منازل «لا يجاوزها ولا يقصر دُونها»؛ ونقل القرطبي عن ابن عباس: لو جعل الله شمسين، شمساً بالنهار وشمساً بالليل، «لم يعلم عدد السنين وحساب الشهور».",en:"Al-Ṭabarī: 'He made the Sun shine and the Moon give light', and set its stations, 'which it neither passes nor falls short of'. Al-Qurṭubī quotes Ibn ʿAbbās: had God made two suns, one by day and one by night, 'the number of years and the reckoning of the months would not be known'.",by:["tabari","qurtubi"],cite:[e("tafsirTabari","10:5","هو الذي أضاء الشمسَ وأنار القمر"),e("tafsirQurtubi","10:5","لم يعلم عدد السنين وحساب الشهور")]},{ar:"وفي «المختصر في التفسير»: جعل الشمس «تشع الضوء وتنشره»، وجعل القمر «نورًا يُسْتنار به»، وقدّر سيره «بعدد منازله الثماني والعشرين»؛ وفي «التفسير الميسر»: «فبالشمس تعرف الأيام، وبالقمر تعرف الشهور والأعوام».",en:"Al-Mukhtaṣar: He made the Sun 'send out light and spread it' and the Moon 'a light to see by', and measured its course 'by its twenty-eight stations'; al-Muyassar: 'by the Sun the days are known, and by the Moon the months and years'.",by:["mukhtasar","muyassar"],cite:[e("tafsirMukhtasar","10:5","جعل الشمس تشع الضوء وتنشره"),e("tafsirMuyassar","10:5","فبالشمس تعرف الأيام، وبالقمر تعرف الشهور والأعوام")]}],show:[{step:"fly",target:{body:"moon"},note:{ar:"القمر الآن، وجهته المضيئة نحو الشمس دائماً — مع سهم إلى جهة الشمس وإن كانت تحت الأفق.",en:"The Moon now, its lit side always toward the Sun — with an arrow to the Sun's direction, even below the horizon."}},{step:"scene",scene:"solar-system",note:{ar:"من خارج الأرض: ضوء الشمس يسقط على الأرض والقمر، فيضيء نصف كل منهما؛ ثم ضوء الأرض على الجزء المظلم من هلال رقيق.",en:"From outside the Earth: sunlight falling on the Earth and the Moon, lighting half of each; then earthshine on the dark part of a thin crescent."}},{step:"overlay",note:{ar:"تنبيه: لا تنظر إلى الشمس مباشرة.",en:"Safety: never look straight at the Sun."}}],science:[{ar:"الشمس نجم يولّد ضوءه بنفسه: في قلبها يندمج الهيدروجين فيصير هيليوماً، وتخرج الطاقة ضوءاً وحرارة، فيصلنا ضوؤها بعد نحو ثماني دقائق وعشرين ثانية.",en:"The Sun is a star that makes its own light: in its core hydrogen fuses into helium, and the energy comes out as light and heat; its light reaches us about eight minutes and twenty seconds later.",cite:[e("najmDetails","PAGE_TEXT.sun.physical[0] (nasaLightDay, skySunLight and the Sun's page sources)"),e("nasaMoonPhases",'"In our entire solar system, the only object that shines with its own light is the Sun."')]},{ar:"أما القمر فلا ضوء له في ذاته: تقول ناسا إن ضوء القمر هو ضوء الشمس منعكساً، وسطحه لا يعكس إلا نحو عُشر ما يسقط عليه منه، ويصلنا ذلك الضوء بعد ثانية وربع تقريباً.",en:"The Moon has no light of its own: NASA puts it plainly — moonlight is reflected sunlight — and its surface reflects only about a tenth of the sunlight that falls on it; that light reaches us about a second and a quarter later.",facts:[{body:"moon",key:"distanceEarth",said:384400}],computed:"384,400 km ÷ 299,792.458 km/s = 1.28 s",cite:[e("nasaMoonPhases",'"The Moon does not make its own light. "Moonlight" is actually reflected sunlight."'),e("nssdcMoon","Bond albedo 0.11"),e("najmDetails","BODY_FACTS.moon: distanceEarth")]},{ar:"وفي الهلال الرقيق قد يظهر باقي قرص القمر خافتاً، وذلك ضوء الشمس منعكساً عن الأرض إلى القمر ثم إلينا.",en:"On a thin crescent the rest of the Moon's disc can sometimes be seen faintly: that is sunlight reflected from the Earth onto the Moon, and back to us.",when:"twilight",cite:[e("nasaMoonPhases",`"This effect is caused by the Sun's light reflecting off Earth's surface onto the face of the Moon."`)]}],reflection:{by:"shaarawi",quote:"فالشمس تعطي ضياء، والقمر يعطي نوراً. والفرق بين الضياء والنور يتمثل في أن الضياء تصحبه الحرارة والدفء، والنور إنارة حليمة … القمر مضيء بغيره، أما الشمس فهي تضيء بذاتها",intro:{ar:"ومن تأملات الشيخ الشعراوي في الفرق بين الكلمتين:",en:"Sheikh al-Shaʿrāwī reflects on the difference between the two words:"},en:'(his words, rendered) "The Sun gives radiance and the Moon gives light. The difference is that radiance comes with heat and warmth, while light is a gentle glow … the Moon shines by another, and the Sun shines by itself."',cite:[e("sharawi","vol. 9 p. 5738 (Shāmila book 1083, p. 6582)","والفرق بين الضياء والنور يتمثل في أن الضياء تصحبه الحرارة والدفء")]}},{id:"sun-course",order:8,narration:"quran-sun-course",title:{ar:"مسير الشمس",en:"The Sun's course"},recite:["36:38"],meaning:[{ar:"فسّر النبي صلى الله عليه وسلم مستقرها بأنه تحت العرش، حيث تذهب فتسجد، في حديث أبي ذر رضي الله عنه عند البخاري (3199، 4802، 4803) ومسلم (159)؛ وبه بدأ الطبري تفسير الآية، وأورده ابن كثير والقرطبي والبغوي، وعليه «الميسر في غريب القرآن».",en:"The Prophet (peace be upon him) explained its resting place as being beneath the Throne, where it goes to prostrate, in the report of Abū Dharr in al-Bukhārī (nos. 3199, 4802, 4803) and Muslim (no. 159); al-Ṭabarī opens his commentary with it, Ibn Kathīr, al-Qurṭubī and al-Baghawī cite it, and the King Fahd Complex's dictionary of rare words follows it.",by:["tabari","ibnKathir","qurtubi","baghawi","gharibMuyassar"],hadith:[{collection:"bukhari",no:[3199,4802,4803],from:{ar:"أبو ذر الغفاري",en:"Abū Dharr al-Ghifārī"}},{collection:"muslim",no:[159],from:{ar:"أبو ذر الغفاري",en:"Abū Dharr al-Ghifārī"}}],cite:[e("bukhari","no. 4803 (Kitāb al-Tafsīr, Yā-Sīn); also 3199 and 4802"),e("muslim","no. 159 (Kitāb al-Īmān)"),e("tafsirTabari","36:38","والشمس تجري لموضع قرارها"),e("tafsirIbnKathir","36:38 (the reports of Abū Dharr)"),e("tafsirQurtubi","36:38","وفي صحيح مسلم عن أبي ذر"),e("tafsirBaghawi","36:38","وقد صح عن النبي - صلى الله عليه وسلم - أنه قال"),e("gharibMuyassar","36:38","مُسْتَقَرُّها تَحْتَ العَرْشِ، كما جاء في الحديثِ المتَّفقِ عَلَيه")]},{ar:"وقال ابن عثيمين عن سجود الشمس الوارد في الحديث: «وهذا السجود لا نعلم كيفيَّته؛ لأن الشمس ليستْ كالبَشَر حتى يُقاس سجودها بسجود البَشَر».",en:"Ibn ʿUthaymīn, on the Sun's prostration mentioned in that report: 'we do not know how this prostration is, for the Sun is not like human beings, that its prostration should be measured by theirs'.",by:["ibnUthaymin"],cite:[e("tafsirIbnUthaymin","Yā-Sīn 38","وهذا السجود لا نعلم كيفيَّته؛ لأن الشمس ليستْ كالبَشَر حتى يُقاس سجودها بسجود البَشَر")]},{ar:"وروى الطبري عن قتادة أن مستقرها «وقت واحد لا تعدوه»، وذكر ابن كثير والبغوي قولاً بأنه منتهى سيرها حين تنقضي الدنيا.",en:"Al-Ṭabarī reports Qatāda: its resting place is 'a single time it does not pass'; Ibn Kathīr and al-Baghawī record the view that it is the end of its course, when this world ends.",by:["tabari","ibnKathir","baghawi"],cite:[e("tafsirTabari","36:38","وقت واحد لا تعدوه"),e("tafsirIbnKathir","36:38","أن المراد بمستقرها هو : منتهى سيرها ، وهو يوم القيامة"),e("tafsirBaghawi","36:38","إلى انتهاء سيرها عند انقضاء الدنيا وقيام الساعة")]},{ar:"وذكر الطبري قولاً ثالثاً: أنها تجري «إلى أبعد منازلها في الغروب، ثم ترجع ولا تجاوزه»، ونقله القرطبي عن الكلبي؛ وقال ابن عثيمين: «فلها حدٌّ تنتهي إليه من الشَّمال لا تتجاوزه، ولها حدٌّ تنتهي إليه من الجنوب لا تتجاوزه»، فببلوغها أقصاها شمالاً يبدأ الصيف، وببلوغها أقصاها جنوباً يبدأ الشتاء.",en:"Al-Ṭabarī records a third view: it runs 'to the farthest of its setting points, then turns back and does not pass it' — al-Qurṭubī gives it from al-Kalbī; Ibn ʿUthaymīn: 'it has a limit in the north that it does not pass, and a limit in the south that it does not pass'; reaching the northern one begins summer, the southern one winter.",by:["tabari","qurtubi","ibnUthaymin"],cite:[e("tafsirTabari","36:38","تجري إلى أبعد منازلها في الغروب، ثم ترجع ولا تجاوزه"),e("tafsirQurtubi","36:38","وقال الكلبي وغيره : المعنى : تجري إلى أبعد منازلها في الغروب"),e("tafsirIbnUthaymin","Yā-Sīn 38","فلها حدٌّ تنتهي إليه من الشَّمال لا تتجاوزه، ولها حدٌّ تنتهي إليه من الجنوب لا تتجاوزه")]},{ar:"وفي تفسير السعدي: مستقرٌّ «قدره اللّه لها، لا تتعداه، ولا تقصر عنه»، ومثله في «التفسير الميسر»؛ وفي «المختصر في التفسير»: «لمستقر يعلم الله قَدْرَه لا تتجاوزه».",en:"Al-Saʿdī: a resting place 'that God set for it, which it neither passes nor falls short of', and al-Muyassar likewise; al-Mukhtaṣar: 'a resting place whose measure God knows, which it does not pass'.",by:["saadi","muyassar","mukhtasar"],cite:[e("tafsirSaadi","36:38","قدره اللّه لها، لا تتعداه، ولا تقصر عنه"),e("tafsirMuyassar","36:38","قدَّره الله لها لا تتعداه ولا تقصر عنه"),e("tafsirMukhtasar","36:38","لمستقر يعلم الله قَدْرَه لا تتجاوزه")]}],show:[{step:"timelapse",target:{horizon:"east"},span:"one year of sunrises, a frame each morning",note:{ar:"موضع شروق الشمس ينتقل شمالاً حتى حدّه في يونيو، ثم يرجع جنوباً حتى حدّه في ديسمبر، ثم يرجع؛ والحدّان محسوبان لمكان المستخدم. وهذا ما يصفه أحد الأقوال أعلاه.",en:"The sunrise point slides north to its June limit, turns back south to its December limit, and turns again; both limits computed for the user's place. This is what one of the views above describes."}},{step:"timelapse",target:{body:"sun"},span:"sunrise to sunset on a solstice and an equinox",note:{ar:"قوس الشمس اليومي في أطول يوم وأقصره ويوم الاعتدال.",en:"The Sun's daily arc on the longest day, the shortest, and an equinox."}},{step:"scene",scene:"galaxy",note:{ar:"ابتعاد إلى مجرتنا: الشمس وكواكبها تسير حول مركز المجرة (رسم توضيحي).",en:"Pull back to our galaxy: the Sun and its planets travelling around the galaxy's centre (illustration)."}},{step:"overlay",note:{ar:"تنبيه: لا تنظر إلى الشمس مباشرة.",en:"Safety: never look straight at the Sun."}}],science:[{ar:"تبدو الشمس كأنها تجري من الشرق إلى الغرب لأن الأرض تدور حول نفسها؛ ويتنقل موضع شروقها على الأفق خلال السنة لأن محور الأرض مائل على مستوى مدارها: ففي الكويت تشرق في يونيو على نحو ثمانٍ وعشرين درجة شمال الشرق، وفي ديسمبر على نحو سبع وعشرين درجة جنوبه، ثم ترجع؛ فيقطع مشرقها على الأفق نحو أربع وخمسين درجة، وفي مكة نحو إحدى وخمسين.",en:"The Sun seems to run from east to west because the Earth turns; its rising point moves along the horizon through the year because the Earth's axis is tilted to the plane of its orbit: in Kuwait it rises about twenty-eight degrees north of east in June and about twenty-seven degrees south of east in December, then turns back — a swing of about fifty-four degrees along the horizon, and about fifty-one in Mecca.",computed:"heritage.ts sunrisePoints(2026): Kuwait 62.3° (Jun) and 116.6° (Dec), swing 54.3°; Mecca 64.3° and 114.9°, swing 50.6°",cite:[e("najmEngine","WP-19 confirmation, item 9")]},{ar:"وفي علم الفلك اليوم أن الشمس نفسها تسير في مجرتنا حاملةً معها كواكبها: تقول ناسا إنها تسير بنحو 720 ألف كيلومتر في الساعة، وتتم دورة حول مركز المجرة في نحو 230 مليون سنة، وفي صفحة أخرى لناسا نحو 240 مليوناً.",en:"Astronomy today adds that the Sun itself travels through our galaxy, carrying its planets with it: NASA says it moves at about 720,000 kilometres an hour and takes about 230 million years to go once around the galaxy's centre — another NASA page says about 240 million.",cite:[e("nasaSun",'"Our solar system is moving with an average velocity of 450,000 miles per hour (720,000 kilometers per hour). But even at this speed, it takes about 230 million years for the Sun to make one complete trip around the Milky Way."'),e("nasaGalaxies",'"Our solar system takes about 240 million years to orbit the Milky Way just once."')]}],reflection:{by:"shaarawi",onVerse:"13:2",quote:"وقد عرفنا أن هناك مطالع متعددة للشمس، وعلى الرغم من أن المشرق له جهة عامة واحدة؛ لكن المطالع مختلفة … فكل يوم توجد لها منزلة مختلفة عن اليوم السابق، وتظل تقطعها، ثم تعود مرة أخرى",intro:{ar:"ويقول الشيخ الشعراوي في تفسيره لآية في سورة الرعد عن جريان الشمس والقمر إلى أجل مسمى (الرعد: 2):",en:"Sheikh al-Shaʿrāwī, explaining a verse of Sūrat al-Raʿd on the Sun and the Moon running for an appointed term (13:2):"},en:'(his words, rendered) "We have come to know that the Sun has many rising points; though the east is one general direction, the risings differ … each day it has a station different from the day before; it keeps crossing them, then returns again."',cite:[e("sharawi","vol. 12 p. 7181 (Shāmila book 1083, p. 8288)","وقد عرفنا أن هناك مطالع متعددة للشمس")]}},{id:"lamps",order:9,narration:"quran-lamps",title:{ar:"مصابيح السماء",en:"Lamps of the sky"},recite:["67:5"],meaning:[{ar:"قال الطبري: المصابيح «هي النجوم، وجعلها مصابيح لإضاءتها»، والسماء الدنيا عند البغوي «الأدنى من الأرض وهي التي يراها الناس»؛ وقال السعدي: لولا ما فيها من النجوم «لكانت سقفًا مظلمًا، لا حسن فيه ولا جمال».",en:"Al-Ṭabarī: the lamps 'are the stars; He made them lamps because they shine'; the nearest heaven, says al-Baghawī, is 'the one nearest the earth, which people see'; al-Saʿdī: without its stars 'it would be a dark roof, with no beauty and no grace'.",by:["tabari","baghawi","saadi"],cite:[e("tafsirTabari","67:5","وهي النجوم، وجعلها مصابيح لإضاءتها"),e("tafsirBaghawi","67:5","أراد الأدنى من الأرض وهي التي يراها الناس"),e("tafsirSaadi","67:5","لكانت سقفًا مظلمًا، لا حسن فيه ولا جمال")]},{ar:"وقال ابن كثير: الضمير في الرجم عائد «على جنس المصابيح لا على عينها؛ لأنه لا يرمي بالكواكب التي في السماء، بل بشهب من دونها»، وقال القرطبي: «فالمصابيح لا تزول ولا يرجم بها»؛ وفي «التفسير الميسر»: جعلناها «شهبًا محرقة لمسترقي السمع من الشياطين»، وأعدّ الله لهم في الآخرة عذاب النار.",en:"Ibn Kathīr: what is thrown refers 'to the kind of lamps, not to the lamps themselves, for the stars in the sky are not what is thrown, but shooting flames below them'; al-Qurṭubī: 'the lamps do not pass away and are not thrown'; al-Muyassar: 'burning flames against the devils who try to eavesdrop', and for them God has prepared the punishment of the Fire in the next life.",by:["ibnKathir","qurtubi","muyassar"],cite:[e("tafsirIbnKathir","67:5","على جنس المصابيح لا على عينها ; لأنه لا يرمي بالكواكب التي في السماء ، بل بشهب من دونها"),e("tafsirQurtubi","67:5","فالمصابيح لا تزول ولا يرجم بها"),e("tafsirMuyassar","67:5","شهبًا محرقة لمسترقي السمع من الشياطين")]},{ar:"وروى الطبري وابن كثير والقرطبي قول قتادة: إن الله إنما خلق هذه النجوم «لثلاث خصال: خلقها زينة للسماء الدنيا، ورجومًا للشياطين، وعلامات يهتدي بها؛ فمن يتأوّل منها غير ذلك، فقد قال برأيه، وأخطأ حظه، وأضاع نصيبه، وتكلَّف ما لا علم له به».",en:"Al-Ṭabarī, Ibn Kathīr and al-Qurṭubī report Qatāda: God created these stars 'for three purposes: an adornment for the nearest heaven, missiles against the devils, and signs to steer by; whoever reads anything else into them speaks from his own opinion, misses his share, loses his portion, and burdens himself with what he has no knowledge of'.",by:["tabari","ibnKathir","qurtubi"],cite:[e("tafsirTabari","67:5","إنما خلق هذه النجوم لثلاث خصال"),e("tafsirIbnKathir","67:5","إنما خلقت هذه النجوم لثلاث خصال"),e("tafsirQurtubi","67:5","خلق الله تعالى النجوم لثلاث")]},{ar:"ونقل القرطبي عن محمد بن كعب: «والله ما لأحد من أهل الأرض في السماء نجم، ولكنهم يتخذون الكهانة سبيلا، ويتخذون النجوم علة».",en:"Al-Qurṭubī quotes Muḥammad ibn Kaʿb: 'By God, no one on earth has a star in the sky; they take soothsaying as their way, and use the stars as the excuse.'",by:["qurtubi"],cite:[e("tafsirQurtubi","67:5","والله ما لأحد من أهل الأرض في السماء نجم")]},{ar:"وفي سورة ق دعوةٌ إلى النظر إلى السماء وكيف بُنيت وزُيّنت (ق: 6)، قال السعدي: «لا يحتاج ذلك النظر إلى كلفة وشد رحل، بل هو في غاية السهولة».",en:"Sūrat Qāf (50:6) invites people to look at the sky above them — how it was built and adorned; al-Saʿdī: 'that looking needs no effort and no journey; it is the easiest thing'.",by:["saadi"],mentions:["50:6"],cite:[e("tafsirSaadi","50:6","لا يحتاج ذلك النظر إلى كلفة وشد رحل، بل هو في غاية السهولة")]}],show:[{step:"scene",scene:"sky",note:{ar:"السماء كلها في ليلة مظلمة: كل النجوم إلى حدّ ما تراه العين، وشريط المجرة حيث يكون فوق الأفق.",en:"The whole sky on a dark night: every star down to the eye's limit, and the Milky Way band where it is up."}},{step:"overlay",note:{ar:"كم نجماً فوق الأفق الآن في فهرس «نجم»، وكم منها يُرى فعلاً من مكان مظلم ومن المدينة — دون أن يسمّى العدد الهندسي «مرئياً».",en:"How many catalogue stars are above the horizon now, and how many of them are actually seen from a dark place and from a city — never calling the geometric count 'seen'."}},{step:"scene",scene:"galaxy",note:{ar:"المجرة من خارجها، وعلامة «أنت هنا» في منتصف الطريق تقريباً من مركزها (رسم توضيحي).",en:"The Milky Way from outside, with 'you are here' about halfway from its centre (illustration)."}},{step:"interact",kind:"free-look",note:{ar:"تأمّل حر.",en:"Free looking."}}],science:[{ar:"كل نجم من هذه النجوم شمسٌ بعيدة؛ ويضم فهرس «نجم» نحو خمسة آلاف نجم، هي تقريباً كل ما تبلغه العين المجردة في السماء كلها في أظلم الليالي، نصفها تقريباً فوق الأفق في أي لحظة؛ لكن ما يُرى منها معاً من مكان مظلم نحو ألف وخمسمئة، لأن ما قرب من الأفق يخفت في الهواء، وفي المدن مئات قليلة.",en:"Every one of these stars is a distant sun; Najm's catalogue holds about five thousand stars — roughly all the eye can reach in the whole sky on the darkest nights — about half of them above the horizon at any moment; but from a dark place about fifteen hundred are seen at once, because stars near the horizon fade in the air, and in a city only a few hundred.",computed:"catalogue: 5,044 stars to V 6.00; 2,342–2,598 above Kuwait's horizon; seen at a dark site after extinction 1,300–1,700 (k 0.25); city limit mag 4 → 220–260",cite:[e("catalog","src/data/catalog.json"),e("najmEngine","WP-19 confirmation, item 10")]},{ar:"والمجرة، درب التبانة، قرص من النجوم يزيد قطره على مئة ألف سنة ضوئية، والأرض في أحد أذرعه في منتصف المسافة تقريباً من مركزه؛ والشريط اللبني الباهت الذي يقطع السماء هو هذا القرص منظوراً من داخله، كما تقول ناسا.",en:"Our galaxy, the Milky Way, is a disc of stars more than a hundred thousand light-years across, with the Earth on one of its arms about halfway out from the centre; the faint milky band across the sky is that disc seen from inside, as NASA explains.",cite:[e("nasaGalaxies",`"It's a spiral galaxy with a disk of stars spanning more than 100,000 light-years. Earth is located along one of the galaxy's spiral arms, about halfway from the center."`),e("nasaGalaxies",'"From our perspective on Earth, the Milky Way looks like a faint, milky band of light arcing across the entire sky … This feature marks the central disk of our home galaxy seen edge on."')]},{ar:"وهذا الشريط باهت، لا يظهر إلا في ليلة مظلمة صافية.",en:"The band is faint: it shows only on a dark, clear night.",when:"dark",cite:[e("nasaGalaxies",'"a faint, milky band of light"')]}]},{id:"star-places",order:10,narration:"quran-star-places",title:{ar:"مواقع النجوم",en:"Where the stars set"},recite:["56:75","56:76"],meaning:[{ar:"اختلف المفسرون في «مواقع النجوم»: فقال مجاهد وقتادة: مساقطها ومغاربها، وقال قتادة في رواية وعطاء: منازلها، وقال الحسن: انكدارها وانتثارها يوم القيامة، وقال ابن عباس: هي نجوم القرآن، أي نزوله مفرَّقاً، وقال الضحاك: هي الأنواء التي كان أهل الجاهلية ينسبون إليها المطر؛ ذكر هذه الأقوال الطبري وابن كثير والقرطبي والبغوي.",en:"The exegetes differ on 'the places of the stars'. Mujāhid and Qatāda: where they set; Qatāda in another report, and ʿAṭāʾ: their stations; al-Ḥasan: their falling and scattering on the Day of Resurrection; Ibn ʿAbbās: the 'stars' of the Qur'an — its revelation in portions; al-Ḍaḥḥāk: the anwāʾ, to which the Arabs before Islam ascribed their rain. Al-Ṭabarī, Ibn Kathīr, al-Qurṭubī and al-Baghawī record these views.",by:["tabari","ibnKathir","qurtubi","baghawi"],cite:[e("tafsirTabari","56:75","قال الحسن انكدارها وانتثارها يوم القيامة"),e("tafsirIbnKathir","56:75","يعني بذلك : الأنواء التي كان أهل الجاهلية إذا مطروا"),e("tafsirQurtubi","56:75","عطاء بن أبي رباح : منازلها"),e("tafsirBaghawi","56:75","وقال جماعة من المفسرين : أراد مغارب النجوم ومساقطها")]},{ar:"ورجّح الطبري أن معناها «مساقط النجوم ومغايبها في السماء»، وبه فسّرها «التفسير الميسر» و«الميسر في غريب القرآن»: «بمساقط النجوم في مغاربها في السماء»، وقال السعدي: «مساقطها في مغاربها».",en:"Al-Ṭabarī judged the likeliest meaning to be 'where the stars fall and vanish in the sky'; al-Muyassar and the King Fahd Complex's dictionary of rare words follow it — 'where the stars set in the sky' — and al-Saʿdī: 'where they fall at their setting'.",by:["tabari","muyassar","gharibMuyassar","saadi"],cite:[e("tafsirTabari","56:75 (his ruling)","فلا أقسم بمساقط النجوم ومغايبها في السماء"),e("tafsirMuyassar","56:75–76","أقسم الله تعالى بمساقط النجوم في مغاربها في السماء"),e("gharibMuyassar","56:75","بِمَساقِطِ النُّجُومِ في مَغارِبِها في السَّماءِ"),e("tafsirSaadi","56:75","مساقطها في مغاربها")]},{ar:"وقال الطبري في الآية التالية: إنه قسم عظيم «لو تعلمون عظمه»؛ وقال السعدي: «وإنما كان القسم عظيما، لأن في النجوم وجريانها، وسقوطها عند مغاربها، آيات وعبرا لا يمكن حصرها»؛ وذكر ابن عثيمين أن المقسَم عليه «من أعظم الأمور»: أن هذا القرآن كريم.",en:"On the next verse, al-Ṭabarī: it is a great oath, 'if you knew its greatness'; al-Saʿdī: 'the oath is great because in the stars, their running and their falling at their setting, there are signs and lessons beyond counting'; Ibn ʿUthaymīn: what is sworn to is 'among the greatest of matters' — that this is a noble Qur'an.",by:["tabari","saadi","ibnUthaymin"],cite:[e("tafsirTabari","56:76","وأنه لقسم عظيم لو تعلمون عظمه"),e("tafsirSaadi","56:76","لأن في النجوم وجريانها، وسقوطها عند مغاربها، آيات وعبرا لا يمكن حصرها"),e("tafsirIbnUthaymin","al-Wāqiʿa 75–77","على أمر من أعظم الأمور")]},{ar:"ومن فوائد هذه الآيات في «المختصر في التفسير»: «الاعتقاد بأن للكواكب أثرًا في نزول المطر كفر وهو من عادات الجاهلية».",en:"Among the lessons al-Mukhtaṣar draws from these verses: 'believing that the stars have a part in bringing down rain is disbelief, and a custom of the time before Islam'.",by:["mukhtasar"],cite:[e("tafsirMukhtasar","56:76 (its notes on the passage)","الاعتقاد بأن للكواكب أثرًا في نزول المطر كفر وهو من عادات الجاهلية")]}],show:[{step:"timelapse",target:{horizon:"west"},span:"three hours after dark",note:{ar:"النجوم تغيب واحداً بعد واحد في الأفق الغربي — «مساقط النجوم ومغاربها» في قول الطبري ومن تبعه.",en:"Stars sinking one after another into the western horizon — 'where the stars fall and set', in al-Ṭabarī's reading."}},{step:"fly",target:{hip:32349},note:{ar:"الشعرى وعليها: خرج ضوؤها قبل قرابة تسع سنين.",en:"Sirius, labelled: its light left it almost nine years ago."}},{step:"fly",target:{hip:11767},note:{ar:"الجُدَيّ: أكثر من أربعة قرون.",en:"Al-Judayy: more than four centuries."}},{step:"fly",target:{dso:"m31"},note:{ar:"مجرة المرأة المسلسلة إن كانت فوق الأفق: نحو مليونين ونصف مليون سنة.",en:"The Andromeda Galaxy, if it is up: about two and a half million years."}},{step:"interact",kind:"tap",note:{ar:"المس أي نجم لترى متى خرج ضوؤه.",en:"Tap any star to see when its light set out."}}],science:[{ar:"تغرب النجوم في الغرب كل ليلة لأن الأرض تدور، ويتقدم موعد غروب كل نجم نحو أربع دقائق كل يوم، فتتبدل سماء المساء مع الفصول.",en:"The stars set in the west every night because the Earth turns, and each star sets about four minutes earlier every day, so the evening sky changes with the seasons.",computed:"sidereal day 23 h 56 min 4.09 s: a star sets 3 min 56 s earlier each day",cite:[e("najmEngine","WP-19 confirmation, item 2a")]},{ar:"والضوء الذي نراه من النجم خرج منه قبل زمن: من الشعرى قبل نحو 8.6 سنة، ومن سُهيل قبل نحو 310 سنين، ومن الجُدَيّ قبل أكثر من أربعة قرون، ومن مجرة المرأة المسلسلة قبل نحو مليونين ونصف مليون سنة؛ فنحن نرى النجوم كما كانت حين خرج ضوؤها.",en:"The light we see from a star left it long ago: from Sirius about 8.6 years ago, from Suhail about 310 years, from al-Judayy more than four centuries, and from the Andromeda Galaxy about two and a half million years — so we see the stars as they were when their light set out.",facts:[{hip:32349,key:"distance",said:8.6},{catalogDist:30438,said:310}],cite:[e("najmDetails","STAR_DETAILS HIP 32349: distance; HIP 11767: distance with its sources-differ note"),e("catalog","HIP 30438 dist (309 ly)"),e("nasaM31",'"Distance 2.5 million light-years"')]}],reflection:{by:"mustafaMahmoud",quote:"وقل ذلك فى موقع كل نجم فجميع الأجرام السماوية مرتبطة ببعضها البعض ارتباط الحبات فى مسبحة",intro:{ar:"وكتب الدكتور مصطفى محمود، بعد أن ذكر أن الله قدّر كل شيء بمقدار، وقبل أن يورد هذه الآية:",en:"Dr Muṣṭafā Maḥmūd wrote, after saying that God made everything in due measure, and just before quoting this verse:"},en:'(his words, rendered) "And say the same of the position of every star: all the heavenly bodies are bound to one another like the beads of a rosary."',cite:[e("mustafaMahmoudAsrar","p. 17","وقل ذلك فى موقع كل نجم")]}}];function m(t,n=new Date){const s=r.flatMap(a=>[{type:"chapter",id:a.id,title:a.title,tail:.2},{type:"scene",at:0,scene:{kind:"quran-reader",stopId:a.id}},{type:"pause",at:0}]);return{journey:{id:"quran",title:i.title,blurb:i.subtitle,free:!0,clips:{},steps:s,quran:{stops:r,verses:l},sources:Object.values(o).map(a=>({text:{ar:a.ar,en:a.en},url:a.url})),credits:[{ar:"النص العثماني: تنزيل. ترجمة المعاني: صحيح إنترناشيونال، موسوعة القرآن الكريم. الخط: أميري قرآن.",en:"Uthmani text: Tanzil. Translation of meanings: Saheeh International, QuranEnc. Typeface: Amiri Quran."}]},zone:h(t),year:n.getUTCFullYear(),stop:()=>{}}}export{m as buildQuranJourney};
